steps.command:
mkdir -p /tmp/s && cat > /tmp/s/a.py <<'E'
import ast,sys,glob,os
for p in sorted(glob.glob('billing/*.py')):
    m=os.path.basename(p)[:-3]
    t=ast.parse(open(p).read())
    def walk(n,pre):
        for c in ast.iter_child_nodes(n):
            if isinstance(c,ast.ClassDef): walk(c,pre+[c.name])
            elif isinstance(c,(ast.FunctionDef,ast.AsyncFunctionDef)):
                rets=[];
                def r(x):
                    for y in ast.iter_child_nodes(x):
                        if isinstance(y,(ast.FunctionDef,ast.Lambda,ast.ClassDef,ast.AsyncFunctionDef)):continue
                        if isinstance(y,ast.Return):rets.append(y)
                        r(y)
                r(c)
                vals=[x for x in rets if x.value is not None and not(isinstance(x.value,ast.Constant) and x.value.value is None)]
                if not vals and not any(x.value is not None for x in rets): continue
                print(f"{m}.{'.'.join(pre+[c.name])}  L{c.lineno}", [ast.unparse(x.value) if x.value else 'bare' for x in rets], 'lastret' if isinstance(c.body[-1],ast.Return) else 'FALLTHRU?')
    walk(t,[])
E
.venv/bin/python -I /tmp/s/a.py
